// Parse test suite configuration
const input = $input.first().json;
const body = input.body || input;

if (!body.tests && !body.testSuite) {
  throw new Error('Missing required field: tests or testSuite');
}

const testSuite = {
  id: `suite_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
  name: body.name || 'Unnamed Test Suite',
  tests: body.tests || body.testSuite || [],
  config: {
    parallel: body.parallel || false,
    stopOnFailure: body.stopOnFailure || false,
    timeout: body.timeout || 30000,
    retries: body.retries || 0
  },
  startedAt: new Date().toISOString(),
  results: []
};

return [{ json: testSuite }];

// Generate mock data based on schema
const suite = $input.first().json;

// Mock data generators
const generators = {
  string: (opts = {}) => {
    const chars = 'abcdefghijklmnopqrstuvwxyz';
    const len = opts.length || 10;
    return Array(len).fill(0).map(() => chars[Math.floor(Math.random() * chars.length)]).join('');
  },
  email: () => `${generators.string({ length: 8 })}@example.com`,
  number: (opts = {}) => {
    const min = opts.min || 0;
    const max = opts.max || 1000;
    return Math.floor(Math.random() * (max - min + 1)) + min;
  },
  boolean: () => Math.random() > 0.5,
  date: () => new Date().toISOString(),
  uuid: () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
    const r = Math.random() * 16 | 0;
    return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
  }),
  array: (opts = {}) => Array(opts.count || 3).fill(0).map(() => opts.itemGenerator ? opts.itemGenerator() : generators.string()),
  object: (schema = {}) => {
    const obj = {};
    for (const [key, type] of Object.entries(schema)) {
      obj[key] = typeof type === 'string' ? generators[type]?.() : generators.string();
    }
    return obj;
  }
};

// Common mock data templates
const mockTemplates = {
  user: () => ({
    id: generators.uuid(),
    email: generators.email(),
    name: generators.string({ length: 12 }),
    createdAt: generators.date()
  }),
  order: () => ({
    id: generators.uuid(),
    customerId: generators.uuid(),
    items: generators.array({ count: generators.number({ min: 1, max: 5 }), itemGenerator: () => ({
      sku: generators.string({ length: 6 }).toUpperCase(),
      quantity: generators.number({ min: 1, max: 10 }),
      price: generators.number({ min: 10, max: 500 })
    })}),
    status: ['pending', 'processing', 'shipped', 'delivered'][Math.floor(Math.random() * 4)],
    createdAt: generators.date()
  }),
  notification: () => ({
    recipient: generators.email(),
    channels: ['email'],
    message: { subject: 'Test', body: 'Test notification body' }
  })
};

// Enhance tests with mock data
const testsWithMocks = suite.tests.map(test => {
  let mockData = test.input || {};

  if (test.mockTemplate && mockTemplates[test.mockTemplate]) {
    mockData = { ...mockTemplates[test.mockTemplate](), ...mockData };
  }

  return {
    ...test,
    id: `test_${Date.now()}_${Math.random().toString(36).substr(2, 5)}`,
    input: mockData,
    status: 'pending'
  };
});

return [{
  json: {
    ...suite,
    tests: testsWithMocks,
    generators: Object.keys(generators),
    templates: Object.keys(mockTemplates)
  }
}];

// Split into individual test cases
const suite = $input.first().json;

return suite.tests.map(test => ({
  json: {
    suiteId: suite.id,
    suiteName: suite.name,
    config: suite.config,
    test
  }
}));

// Execute individual test
const data = $input.first().json;
const test = data.test;
const startTime = Date.now();

let result;
let passed = false;
let error = null;

try {
  // Simulate workflow execution based on test type
  // In production, this would call Execute Workflow or HTTP Request

  switch (test.type) {
    case 'http':
      // Simulated HTTP test
      result = {
        statusCode: 200,
        body: { success: true, data: test.input }
      };
      break;

    case 'transform':
      // Simulated data transformation test
      result = {
        transformed: true,
        input: test.input,
        output: { ...test.input, processed: true }
      };
      break;

    case 'validation':
      // Simulated validation test
      const isValid = test.input && Object.keys(test.input).length > 0;
      result = {
        valid: isValid,
        errors: isValid ? [] : ['Empty input']
      };
      break;

    default:
      // Generic test
      result = {
        executed: true,
        input: test.input
      };
  }

  // Run assertions
  if (test.assertions) {
    const assertionResults = [];

    for (const assertion of test.assertions) {
      let assertionPassed = false;

      switch (assertion.type) {
        case 'equals':
          assertionPassed = JSON.stringify(result[assertion.path]) === JSON.stringify(assertion.expected);
          break;
        case 'contains':
          assertionPassed = JSON.stringify(result).includes(assertion.expected);
          break;
        case 'exists':
          assertionPassed = result[assertion.path] !== undefined;
          break;
        case 'statusCode':
          assertionPassed = result.statusCode === assertion.expected;
          break;
        default:
          assertionPassed = true;
      }

      assertionResults.push({
        ...assertion,
        passed: assertionPassed
      });
    }

    passed = assertionResults.every(a => a.passed);
    result.assertions = assertionResults;
  } else {
    passed = true; // No assertions = pass
  }

} catch (e) {
  error = e.message;
  passed = false;
}

const duration = Date.now() - startTime;

return [{
  json: {
    suiteId: data.suiteId,
    test: {
      ...test,
      status: passed ? 'passed' : 'failed',
      duration,
      result,
      error,
      executedAt: new Date().toISOString()
    }
  }
}];

// Collect and aggregate results
const results = $input.all().map(i => i.json);
const suiteId = results[0]?.suiteId;

const tests = results.map(r => r.test);
const passed = tests.filter(t => t.status === 'passed').length;
const failed = tests.filter(t => t.status === 'failed').length;
const totalDuration = tests.reduce((sum, t) => sum + (t.duration || 0), 0);

const report = {
  suiteId,
  summary: {
    total: tests.length,
    passed,
    failed,
    passRate: ((passed / tests.length) * 100).toFixed(2) + '%',
    duration: totalDuration + 'ms',
    status: failed === 0 ? 'PASSED' : 'FAILED'
  },
  tests: tests.map(t => ({
    id: t.id,
    name: t.name || t.type,
    status: t.status,
    duration: t.duration + 'ms',
    error: t.error,
    assertions: t.result?.assertions
  })),
  completedAt: new Date().toISOString()
};

return [{ json: report }];

// Generate test report
const report = $input.first().json;

// Generate markdown report
const markdown = `
# Test Report: ${report.suiteId}

## Summary
- **Status**: ${report.summary.status}
- **Total Tests**: ${report.summary.total}
- **Passed**: ${report.summary.passed}
- **Failed**: ${report.summary.failed}
- **Pass Rate**: ${report.summary.passRate}
- **Duration**: ${report.summary.duration}

## Test Results

| Test | Status | Duration | Error |
|------|--------|----------|-------|
${report.tests.map(t => `| ${t.name} | ${t.status === 'passed' ? '✅' : '❌'} ${t.status} | ${t.duration} | ${t.error || '-'} |`).join('\n')}

---
*Generated at ${report.completedAt}*
`.trim();

// CI/CD exit code (0 = success, 1 = failure)
const exitCode = report.summary.failed === 0 ? 0 : 1;

return [{
  json: {
    ...report,
    markdown,
    cicd: {
      exitCode,
      status: exitCode === 0 ? 'success' : 'failure',
      github: {
        conclusion: exitCode === 0 ? 'success' : 'failure',
        output: {
          title: `Test Suite: ${report.summary.status}`,
          summary: `${report.summary.passed}/${report.summary.total} tests passed (${report.summary.passRate})`
        }
      }
    }
  }
}];
